const fs=require('fs'),path=require('path'),vm=require('vm'),crypto=require('crypto'),assert=require('assert');
const root=path.resolve(__dirname,'..'),ctx={window:{}},tmp=require('fs').mkdtempSync(path.join(require('os').tmpdir(),'te-bundle-'));require('child_process').execFileSync(process.execPath,[path.join(root,'scripts/reassemble_data.js'),tmp]);vm.createContext(ctx);
for(const file of ['data/study.js','data/loci.js',...['Klf6','Fndc9','Rgs4','Rasl11b','Btg2','Ascl1'].map(x=>`data/loci/${x}.js`)])vm.runInContext(fs.readFileSync(file.startsWith('data/loci/')?path.join(tmp,'loci',path.basename(file)):path.join(root,file),'utf8'),ctx);
const d=ctx.window.STUDY_DATA,L=ctx.window.LOCI_DATA;assert.strictEqual(d.rna.length,64);assert.strictEqual(L.length,6);
for(const locus of L){assert.strictEqual(locus.schema,'satb2-locus-v1');assert.strictEqual(locus.bin_size,5000);assert.strictEqual(locus.samples.join('|'),'Flx NBQX|Flx BIC|cKO NBQX|cKO BIC');assert.strictEqual(locus.matrices.length,4);assert.strictEqual(locus.te_tracks.length,4);assert.strictEqual(locus.loops.length,4);for(const m of locus.matrices){let n=(locus.end-locus.start)/5000;assert.strictEqual(m.length,n);assert(m.every(r=>r.length===n&&r.every(x=>x===null||(Number.isFinite(x)&&x>=0))))}for(const name of ['ATAC','H3K27ac','H3K4me3_floxed_reference','H3K27me3_floxed_reference'])assert(locus.coverage[name]&&locus.coverage[name].length===4);assert(!Object.keys(locus.coverage).some(x=>/H3K9/i.test(x)));}
const hashes={'condition_specific_loops.tsv.gz':'67abc22f48e10e68608742675581e583f395129fb306d1fdbf3270600a929d95','selected_region_TE_copy_links_divergence.tsv.gz':'455b51ec7ae0b8804778381491d25848ed40495a5f1fa5df6b4b28070eeb3af5','RNA_1h_culture_cluster_values.tsv':'263d91ffd8a8ef585640976b4a38ccc6a03721782835c7968fa9425ac8d1174f','RNA_1h_paired_wilcoxon_tests.tsv':'dfe7fd6a65728b3c70c66a527240a9c06207d2be9d2f96ed0ef6597467eb14d2','TE_age15_counts_and_percent.tsv':'c7c6ca7855a598c0ac694d480f54f50e156132b4be458ca6a58bf83d26d0dcb3'};for(const [name,hash] of Object.entries(hashes)){let actual=crypto.createHash('sha256').update(fs.readFileSync(name==='condition_specific_loops.tsv.gz'?path.join(tmp,name):path.join(root,'data/downloads',name))).digest('hex');assert.strictEqual(actual,hash,name)}
